('$($script:WorkspaceId)','$recordA','CONTACT','$buyerA','order_record_a','payment_intent_read_a','PAYMENT','SUCCEEDED',150.250000,'USD','CARD','ONLINE_GATEWAY','provider_alpha',NULL,NULL,NULL,'2026-08-30T10:00:00+00:00','external-a',N'[{"id":"evidence_a","type":"PAYMENT_PROOF","fileName":"proof.pdf","mimeType":"application/pdf","url":"/evidence/a","externalReference":"provider-proof-a","capturedAt":"2026-08-30T10:01:00Z","capturedBy":"member_a","verificationState":"VERIFIED","notes":"verified","lockedByBusinessEvent":true,"createdAt":"2026-08-30T10:02:00Z"}]','MATCHED','COLLECTED','REMITTED',1,7,'2026-08-30T10:00:00+00:00','2026-08-30T11:00:00+00:00',N'[{"id":"allocation_a","workspaceId":"$($script:WorkspaceId)","buyerRef":{"type":"CONTACT","id":"$buyerA"},"invoiceId":"invoice_a","sourceType":"PAYMENT_RECORD","sourceId":"$recordA","scheduleLineId":"schedule_a","amount":{"amount":"100.25","currency":"USD"},"state":"EFFECTIVE","resourceVersion":2,"createdAt":"2026-08-30T10:05:00Z","auditEvidenceIds":["audit_a"]}]',N'[{"id":"refund_a","workspaceId":"$($script:WorkspaceId)","sourceReturnId":"return_a","buyerRef":{"type":"CONTACT","id":"$buyerA"},"orderId":"order_record_a","invoiceIds":["invoice_a"],"source":{"type":"PAYMENT_RECORD","id":"$recordA"},"amount":{"amount":"10","currency":"USD"},"state":"PROCESSING","reasonCode":"CUSTOMER_REQUEST","reason":"Customer requested refund","resourceVersion":1,"createdAt":"2026-08-30T10:06:00Z","updatedAt":"2026-08-30T10:07:00Z","providerCode":"provider_alpha","latestProviderAttemptId":"attempt_a"}]',N'[{"id":"credit_a","workspaceId":"$($script:WorkspaceId)","buyerRef":{"type":"CONTACT","id":"$buyerA"},"sourcePaymentRecordId":"$recordA","originalAmount":{"amount":"20","currency":"USD"},"availableAmount":{"amount":"15","currency":"USD"},"state":"PARTIALLY_ALLOCATED","resourceVersion":3,"createdAt":"2026-08-30T10:08:00Z","updatedAt":"2026-08-30T10:09:00Z"}]',50.000000,'USD',40.000000,'USD'),
